# ---- More programming: debugging, C/C++, Python, Linux, git, embedded C ----
def ex(q, a, q_en, a_en, *aliases):
    e = {'question': q, 'answer': a, 'question_en': q_en, 'answer_en': a_en}
    if aliases:
        e['aliases'] = list(aliases)
    return e

PROGRAMMING_MORE = [
 ex('Как пользоваться gdb?', 'Основное в gdb:\n- `gdb ./app` → `run аргументы`;\n- `break файл.cpp:42` или `break функция`, `info breakpoints`;\n- `next` (шаг через), `step` (внутрь), `finish` (до выхода), `continue`;\n- `print x`, `display x`, `ptype x`, `info locals`;\n- `bt` — стек вызовов, `frame N`;\n- `watch x` — остановиться, когда x изменится.\nСобирайте с `-g -O0`. Для МК — `arm-none-eabi-gdb` + OpenOCD (`target extended-remote :3333`).',
    'How do I use gdb?', 'gdb essentials:\n- `gdb ./app` → `run args`;\n- `break file.cpp:42` or `break function`, `info breakpoints`;\n- `next` (step over), `step` (into), `finish` (out), `continue`;\n- `print x`, `display x`, `ptype x`, `info locals`;\n- `bt` — the call stack, `frame N`;\n- `watch x` — stop when x changes.\nBuild with `-g -O0`. For an MCU: `arm-none-eabi-gdb` + OpenOCD (`target extended-remote :3333`).', 'gdb', 'отладчик gdb', 'how to use gdb'),
 ex('Как найти утечку памяти?', '1. `valgrind --leak-check=full ./app` — покажет, где выделена утёкшая память.\n2. Или собрать с `-fsanitize=address` — LeakSanitizer выведет отчёт при выходе.\n3. В C++ избегайте ручных new/delete: std::unique_ptr, контейнеры, RAII.\n4. Для долгоживущих процессов смотрите рост памяти (heaptrack, massif).',
    'How do I find a memory leak?', '1. `valgrind --leak-check=full ./app` — shows where the leaked memory was allocated.\n2. Or build with `-fsanitize=address` — LeakSanitizer prints a report on exit.\n3. In C++ avoid manual new/delete: std::unique_ptr, containers, RAII.\n4. For long-running processes watch the memory grow (heaptrack, massif).', 'утечка памяти', 'memory leak'),
 ex('Что такое const в C++?', '`const int x` — значение не меняется. `const T &p` — функция только читает аргумент (без копии). `void f() const` — метод не меняет объект. `const int *p` — нельзя менять то, на что указывает p; `int *const p` — нельзя перенаправить p. `constexpr` — значение известно при компиляции. Правило: ставьте const везде, где можно, — компилятор поймает ошибки.',
    'What does const mean in C++?', '`const int x` — the value never changes. `const T &p` — the function only reads the argument (no copy). `void f() const` — the method does not change the object. `const int *p` — you can\'t change what p points to; `int *const p` — you can\'t redirect p. `constexpr` — known at compile time. Rule: use const wherever you can — the compiler will catch mistakes.', 'const', 'константы в c++'),
 ex('Что такое move-семантика?', 'Перемещение (`std::move`) передаёт ресурсы объекта (буфер строки, память вектора) другому объекту вместо копирования — дёшево. После перемещения исходный объект остаётся в корректном, но неопределённом состоянии. Возвращайте объекты из функций по значению — компилятор переместит или вообще уберёт копию (RVO). Для своих классов с ресурсами реализуйте move-конструктор и move-присваивание (или следуйте «правилу нуля» — используйте RAII-члены).',
    'What are move semantics?', 'Moving (`std::move`) hands an object\'s resources (a string buffer, vector memory) to another object instead of copying — cheap. The moved-from object stays valid but unspecified. Return objects from functions by value — the compiler moves or elides the copy (RVO). For your own resource-owning classes write a move constructor and move assignment (or follow the rule of zero — use RAII members).', 'std::move', 'move semantics'),
 ex('Как работать с битами в C?', 'Установить бит: `x |= (1u << n)`; сбросить: `x &= ~(1u << n)`; инвертировать: `x ^= (1u << n)`; проверить: `if (x & (1u << n))`. Поле из нескольких битов: `(x >> pos) & ((1u << width) - 1)`; записать: `x = (x & ~(mask << pos)) | ((v & mask) << pos)`. Используйте беззнаковые типы (uint32_t) — сдвиги знаковых могут быть UB. Калькулятор «Системы счисления» покажет число в hex и двоичном.',
    'How do I work with bits in C?', 'Set a bit: `x |= (1u << n)`; clear: `x &= ~(1u << n)`; toggle: `x ^= (1u << n)`; test: `if (x & (1u << n))`. A multi-bit field: `(x >> pos) & ((1u << width) - 1)`; write it: `x = (x & ~(mask << pos)) | ((v & mask) << pos)`. Use unsigned types (uint32_t) — shifting signed values can be UB. The \"Number bases\" calculator shows a number in hex and binary.', 'битовые операции', 'bit manipulation'),
 ex('Что такое виртуальное окружение Python?', 'venv — отдельная копия Python с собственными пакетами для проекта: `python3 -m venv .venv`, `source .venv/bin/activate`, `pip install -r requirements.txt`. Так зависимости разных проектов не конфликтуют, а системный Python не трогается (в Ubuntu pip в систему запрещён — PEP 668). Сохраните версии: `pip freeze > requirements.txt`.',
    'What is a Python virtual environment?', 'A venv is a separate copy of Python with its own packages per project: `python3 -m venv .venv`, `source .venv/bin/activate`, `pip install -r requirements.txt`. Projects\' dependencies don\'t clash and the system Python stays untouched (Ubuntu forbids pip into the system — PEP 668). Pin versions: `pip freeze > requirements.txt`.', 'venv', 'виртуальное окружение', 'python venv'),
 ex('Как читать трассировку ошибки Python?', 'Traceback читают снизу вверх: последняя строка — тип и текст исключения (`KeyError: \'name\'`), над ней — строка вашего кода, где оно возникло, выше — цепочка вызовов. Частые: `NameError` — опечатка в имени, `TypeError` — не тот тип аргумента, `KeyError`/`IndexError` — нет такого ключа/индекса, `AttributeError: \'NoneType\'` — функция вернула None. Пришлите traceback целиком — разберу.',
    'How do I read a Python traceback?', 'Read a traceback bottom-up: the last line is the exception type and message (`KeyError: \'name\'`), above it the line of your code where it happened, further up the chain of calls. Common ones: `NameError` — a typo in a name, `TypeError` — wrong argument type, `KeyError`/`IndexError` — no such key/index, `AttributeError: \'NoneType\'` — a function returned None. Send me the whole traceback and I\'ll explain it.', 'traceback', 'ошибка python'),
 ex('Что такое async и await?', 'async/await — асинхронный код: функция `async def` может приостановиться на `await` (ожидание сети, файла, таймера), пока выполняется другое. В Python это asyncio (`asyncio.run(main())`), в JS — промисы. Подходит для множества операций ввода-вывода; для тяжёлых вычислений нужны процессы или потоки. Не вызывайте блокирующие функции (time.sleep, requests) внутри async — используйте asyncio.sleep, aiohttp.',
    'What are async and await?', 'async/await is asynchronous code: an `async def` function can pause at `await` (waiting for the network, a file, a timer) while something else runs. In Python that is asyncio (`asyncio.run(main())`), in JS promises. Good for many I/O operations; heavy computation needs processes or threads. Don\'t call blocking functions (time.sleep, requests) inside async code — use asyncio.sleep, aiohttp.', 'async await', 'асинхронность'),
 ex('Как написать юнит-тест?', 'Тест проверяет одну функцию на известных входах: подготовка → вызов → проверка. Python: `pytest`, файл `test_x.py`, функции `test_…` с `assert`. C++: GoogleTest (`TEST(Suite, Name) { EXPECT_EQ(f(2), 4); }`) или Qt Test. Проверяйте граничные случаи (0, пустое, максимум, ошибочный ввод). Тестируйте поведение, а не внутренности. Попросите — напишу тесты к вашему файлу (скрепка).',
    'How do I write a unit test?', 'A test checks one function on known inputs: arrange → act → assert. Python: `pytest`, a `test_x.py` file, `test_…` functions with `assert`. C++: GoogleTest (`TEST(Suite, Name) { EXPECT_EQ(f(2), 4); }`) or Qt Test. Check edge cases (0, empty, maximum, bad input). Test behaviour, not internals. Ask me and I\'ll write tests for your file (paperclip).', 'юнит тест', 'unit test', 'pytest'),
 ex('Как решить конфликт в git?', '1. `git status` покажет файлы с конфликтом.\n2. В файле найдите блоки `<<<<<<<` (ваше), `=======`, `>>>>>>>` (чужое), оставьте правильный вариант, уберите маркеры.\n3. `git add файл`, затем `git commit` (при merge) или `git rebase --continue`.\n4. Передумали — `git merge --abort` / `git rebase --abort`.\nУдобно в VS Code: «Accept Current/Incoming/Both».',
    'How do I resolve a git conflict?', '1. `git status` shows the conflicted files.\n2. In each file find the `<<<<<<<` (yours), `=======`, `>>>>>>>` (theirs) blocks, keep the right version and remove the markers.\n3. `git add file`, then `git commit` (for a merge) or `git rebase --continue`.\n4. Changed your mind — `git merge --abort` / `git rebase --abort`.\nVS Code helps: \"Accept Current/Incoming/Both\".', 'конфликт git', 'merge conflict'),
 ex('Как работает systemd-сервис?', 'Юнит в `~/.config/systemd/user/имя.service` (или /etc/systemd/system для системных):\n```ini\n[Unit]\nDescription=My app\n[Service]\nExecStart=/usr/bin/myapp\nRestart=on-failure\n[Install]\nWantedBy=default.target\n```\nЗатем `systemctl --user daemon-reload`, `systemctl --user enable --now имя`. Логи: `journalctl --user -u имя -f`.',
    'How does a systemd service work?', 'A unit in `~/.config/systemd/user/name.service` (or /etc/systemd/system for system services):\n```ini\n[Unit]\nDescription=My app\n[Service]\nExecStart=/usr/bin/myapp\nRestart=on-failure\n[Install]\nWantedBy=default.target\n```\nThen `systemctl --user daemon-reload`, `systemctl --user enable --now name`. Logs: `journalctl --user -u name -f`.', 'systemd', 'сервис systemd'),
 ex('Как прошить микроконтроллер из командной строки?', 'STM32: `st-flash write firmware.bin 0x08000000` (ST-Link) или `openocd -f interface/stlink.cfg -f target/stm32f1x.cfg -c "program firmware.elf verify reset exit"`. AVR/Arduino: `avrdude -c arduino -p m328p -P /dev/ttyUSB0 -b 115200 -U flash:w:firmware.hex`. ESP32: `esptool.py --port /dev/ttyUSB0 write_flash 0x0 firmware.bin` (или `idf.py flash`). RP2040: зажать BOOTSEL и скопировать .uf2. Доступ к порту: добавьте себя в группу `dialout`.',
    'How do I flash a microcontroller from the command line?', 'STM32: `st-flash write firmware.bin 0x08000000` (ST-Link) or `openocd -f interface/stlink.cfg -f target/stm32f1x.cfg -c "program firmware.elf verify reset exit"`. AVR/Arduino: `avrdude -c arduino -p m328p -P /dev/ttyUSB0 -b 115200 -U flash:w:firmware.hex`. ESP32: `esptool.py --port /dev/ttyUSB0 write_flash 0x0 firmware.bin` (or `idf.py flash`). RP2040: hold BOOTSEL and copy the .uf2. Port access: add yourself to the `dialout` group.', 'прошивка мк', 'flash firmware', 'avrdude', 'openocd'),
]

