def main():
    for path in sorted(S.glob('*.json')):
        data = json.loads(path.read_text(encoding='utf-8'))
        if data['id'] == 'programming':
            known = {e['question'] for e in data['examples']}
            data['examples'] += [e for e in PROGRAMMING_MORE if e['question'] not in known]
            titles = {f['title'] for f in data['formulas']}
            data['formulas'] += [{k: v for k, v in f.items() if v} for f in PROGRAMMING_FORMULAS if f['title'] not in titles]
            data['tools'] = sorted(set(data.get('tools', [])) | {'bases', 'crc', 'epoch', 'bits'})
            if PROGRAMMING_PROMPT_EXTRA.strip() not in data['prompt']:
                data['prompt'] += PROGRAMMING_PROMPT_EXTRA
        if data['id'] == 'embedded':
            data['tools'] = sorted(set(data.get('tools', [])) | {'crc', 'bits'})
        missing = []
        for e in data['examples']:
            if 'question_en' in e:
                continue
            if e['question'] not in EXAMPLES:
                missing.append(e['question'])
                continue
            e['question_en'], e['answer_en'] = EXAMPLES[e['question']]
        for f in data.get('formulas', []):
            if f.get('note') and not f.get('note_en'):
                if f['note'] in NOTES:
                    f['note_en'] = NOTES[f['note']]
                else:
                    missing.append(f['note'])
        path.write_text(json.dumps(data, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')
        print(path.name, len(data['examples']), 'examples', 'MISSING: ' + ' | '.join(missing) if missing else 'complete')


if __name__ == '__main__':
    main()
